mapper.select:
SELECT 
FROM device


        AND INSTR(device.name, #{queryForm.name})


        AND INSTR(device.device_key, #{queryForm.deviceKey})


        AND device.product_id = #{queryForm.productId}


        AND INSTR(device.product_name, #{queryForm.productName})


        AND device.status = #{queryForm.status}


        AND device.gateway_id = #{queryForm.gatewayId}



    ORDER BY device.id DESC
